#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and C4 with the same values as the original C code.
 *
 * Original C layout:
 *   A[NR][NQ][NP]  accessed as A[i][j][k]
 *   C4[NP][NP]     accessed as C4[i][j]
 *
 * Halide layout:
 *   A(p, q, r)  with Buffer size (NP, NQ, NR)
 *     mapping: A(p, q, r) == A_c[r][q][p]
 *
 *   C4(p, s) with Buffer size (NP, NP)
 *     mapping: C4(p, s) == C4_c[s][p]
 */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var i("i"), j("j");

    Func init_A("init_A"), init_C4("init_C4");

    // Cast scalar `np` into an Expr once, then reuse.
    Expr np_expr = Expr(np);

    // A[i][j][k] = ( (i*j + k) % np ) / np;
    // Mapping: i -> r, j -> q, k -> p  =>  A(p, q, r)
    Expr a_val = (r * q + p) % np_expr;
    init_A(p, q, r) = cast<num_t>(a_val) / cast<num_t>(np_expr);

    // C4[i][j] = ( (i*j) % np ) / np;
    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    Expr c4_val = (j * i) % np_expr;
    init_C4(i, j) = cast<num_t>(c4_val) / cast<num_t>(np_expr);

    // Simple, but reasonably efficient schedule for initialization:
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Parallelize across the slowest-varying dimension and vectorize across p / i.
    init_A
        .parallel(r)
        .vectorize(p, vec_width);
    init_C4
        .parallel(j)
        .vectorize(i, vec_width);

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    doitgen(p, q, r) = cast<num_t>(Expr(0));
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // ------------------------------------------------------------------
    // Optimized schedule
    //
    // Goal:
    //   * Keep p (NP dimension) as the innermost loop for unit-stride
    //     access and efficient vectorization of C4(p, s).
    //   * Fuse r and q into a single dimension so we can parallelize
    //     over (r, q) pairs without nested parallelism.
    //   * Optionally tile the fused (r, q) dimension to control
    //     parallel granularity.
    //   * Preserve semantics of original loop nest (r, q, p, s) while
    //     improving locality and using all CPU cores.
    // ------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    // Tuneable tile size for the fused (r, q) dimension. This can be
    // adjusted for different cache hierarchies / core counts.
    const int qr_tile = 64;

    // New fused and tiled vars.
    Var qr("qr"), qr_outer("qr_outer"), qr_inner("qr_inner");

    // Compute the main result at root so we can freely parallelize.
    doitgen.compute_root();

    // 1) Fuse q and r into a single dimension 'qr'.
    //
    //    Logical mapping:
    //      qr = r * nq + q
    //
    //    This preserves the relative order of (r, q) pairs while
    //    allowing us to parallelize across them without nested
    //    parallelism.
    doitgen
        .fuse(q, r, qr)
        // 2) Tile the fused dimension to create reasonably sized
        //    chunks for the thread pool to work on.
        .split(qr, qr_outer, qr_inner, qr_tile)
        // 3) Parallelize across tiles of (r, q).
        .parallel(qr_outer)
        // 4) Vectorize across p for good throughput on the NP
        //    dimension. C4(p, s) is contiguous in memory along p, so
        //    this yields dense vector loads/stores.
        .vectorize(p, vec_width);

    // For the update (reduction) step we need a consistent loop
    // structure. After fuse+split above, the pure dims are:
    //    p, qr_outer, qr_inner
    // and the reduction dim is s.
    //
    // We want:
    //    for qr_outer (parallel)
    //      for qr_inner
    //        for s
    //          for p (vectorized)
    //
    // so that for a given (r, q) tile, we iterate over all s and do
    // dense vector ops over p.
    doitgen.update()
        .reorder(p, s, qr_inner, qr_outer)  // args are from innermost to outermost
        .parallel(qr_outer)
        .vectorize(p, vec_width);

    // Bind JIT and compile with the chosen target
    doitgen.compile_jit(target);

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
