    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    init_C4(i, j) =
        cast<num_t>((j * i) % np) / cast<int>(np);

    // --- Initialization schedule ---
    const int vec_width = get_vector_width();

    // Initialize A in blocks of rows along p:
    //  - r is outer and parallel: each thread gets a z-slice.
    //  - p is innermost and vectorized for contiguous writes.
    init_A
        .compute_root()
        .parallel(r)
        .vectorize(p, vec_width);

    // Initialize C4:
    //  - j (row) outer and parallel.
    //  - i (column) innermost and vectorized.
    init_C4
        .compute_root()
        .parallel(j)
        .vectorize(i, vec_width);

    init_A.realize(A);
    init_C4.realize(C4);
