    // The naive schedule (no directives) produces loop order:
    //   for r
    //     for q
    //       for p
    //         doitgen(p,q,r) = 0
    //       for p
    //         for s
    //           doitgen(p,q,r) += A(s,q,r) * C4(p,s);
