    // contiguously along p for each s, and p is vectorizable.
    //
    // We implement this by reordering the update stage to
    //   p (innermost), then s, then q, then r (outermost),
    // and vectorizing p, parallelizing r.
    //

    // Choose a reasonable vector width based on the host target and element type.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Schedule for the pure (initialization) stage.
    doitgen
        .compute_root()          // compute the whole result at root
        .reorder(p, q, r)        // make p innermost for the pure stage
        .vectorize(p, vec_width) // vectorize zero-initialization across p
        .parallel(r);            // parallelize across independent r-slabs

    // Schedule for the reduction (update) stage.
    doitgen.update()
        // Reorder so that, for each (r,q), we loop s (reduction) outer
        // and p (output index) innermost:
        //
        // Overall order: r (outer) -> q -> s -> p (innermost)
        // The arguments to reorder are listed from innermost outwards.
        .reorder(p, s, q, r)
        .vectorize(p, vec_width) // vectorize across contiguous p
        .parallel(r);            // parallelize across r

    // Bind JIT and compile with the chosen target
    doitgen.compile_jit(target);

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
