        .parallel(r)          // distribute different 'r' planes across threads
        .vectorize(p, vec);   // vectorize along contiguous p

    // C4 is laid out as (p, s), with p contiguous in memory.
    init_C4
        .compute_root()
        .parallel(j)          // parallelize across rows
        .vectorize(i, vec);   // vectorize across contiguous i (== p)

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    doitgen(p, q, r) = cast<num_t>(0);
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // ------------------------------------------------------------------
    // Optimized schedule for doitgen
    //
    // Layout recap:
    //   doitgen(p, q, r)   : p is contiguous in memory (dim 0)
    //   A_param(s, q, r)   : s is dim 0, q dim 1, r dim 2
    //   C4_param(p, s)     : p is dim 0, s dim 1
    //
    // We want:
    //   - p as innermost loop, vectorized
    //   - parallelism across (q, r) planes
    //   - some tiling across the reduction dim 's' to improve locality
    //
    // The reduction is a dot-product between a scalar A(r,q,s) and a
    // vector slice of C4(p,s) across p. Vectorizing over p generates
    // efficient vector code: A(r,q,s) is broadcast, C4(p,s) is loaded
    // as a contiguous vector.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = natural_vector_size(type_of<num_t>(), target);

    // Compute entire output at root.
    doitgen.compute_root();

    // Fuse q and r so we can parallelize across the combined (r,q) space.
    Var qr("qr");
    doitgen
        .fuse(q, r, qr)
        .parallel(qr)          // multi-core parallelism across (r,q)
        .vectorize(p, vec);    // vectorize along contiguous p

    // Optimize the reduction update:
    // - Split the reduction over 's' into tiles (s_outer, s_inner)
    // - Keep 'p' innermost for vectorization
    // - Unroll the small inner reduction tile for better ILP
    RVar s_outer("s_outer"), s_inner("s_inner");
    const int s_tile = 8;  // tunable tile size for reduction over NP
    doitgen.update()
        .split(s, s_outer, s_inner, s_tile)
        // Order from innermost to outermost: p, s_inner, s_outer, qr
        .reorder(p, s_inner, s_outer, qr)
        .vectorize(p, vec)
        .unroll(s_inner);

    // Bind JIT and compile with the chosen target
    doitgen.compile_jit(target);

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}

