#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and C4 with the same values as the original C code.
 *
 * Original C layout:
 *   A[NR][NQ][NP]  accessed as A[i][j][k]
 *   C4[NP][NP]     accessed as C4[i][j]
 *
 * Halide layout:
 *   A(p, q, r)  with Buffer size (NP, NQ, NR)
 *     mapping: A(p, q, r) == A_c[r][q][p]
 *
 *   C4(p, s) with Buffer size (NP, NP)
 *     mapping: C4(p, s) == C4_c[s][p]
 */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var i("i"), j("j");

    Func init_A("init_A"), init_C4("init_C4");

    // A[i][j][k] = ( (i*j + k) % np ) / np;
    // Mapping: i -> r, j -> q, k -> p  =>  A(p, q, r)
    init_A(p, q, r) =
        cast<num_t>((r * q + p) % np) / cast<int>(np);

    // C4[i][j] = ( (i*j) % np ) / np;
    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    init_C4(i, j) =
        cast<num_t>((j * i) % np) / cast<int>(np);

    // -----------------------------------------------------------------
    // Schedule for initialization
    // -----------------------------------------------------------------
    // Use a reasonable vector width for the current host and element type.
    Target init_target = get_host_target();
    const int init_vec = natural_vector_size(init_target, type_of<num_t>());

    Var po("po"), pi("pi");
    Var io("io"), ii("ii");

    // A(p, q, r) is stored with p (dim 0) contiguous, so vectorize over p.
    init_A
        .split(p, po, pi, init_vec)
        .reorder(pi, po, q, r)   // r outer, then q, then tiles of p, then vector lanes
        .parallel(r)
        .vectorize(pi);

    // C4(i, j) is stored with i (dim 0) contiguous, so vectorize over i.
    init_C4
        .split(i, io, ii, init_vec)
        .reorder(ii, io, j)
        .parallel(j)
        .vectorize(ii);

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, np, "s");  // 0 <= s < NP

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    doitgen(p, q, r) = cast<num_t>(0);
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // -----------------------------------------------------------------
    // Optimized schedule for doitgen
    // -----------------------------------------------------------------
    // We keep the mathematical expression identical, but:
    //   - Parallelize over 'r' (outermost dimension, NR >= #cores).
    //   - Vectorize across 'p' (contiguous dimension in memory).
    //   - Keep the reduction over 's' innermost w.r.t. 'p' so that the
    //     summation order per (q,r,p) is unchanged (bitwise stable).
    //
    // The memory layout for A_out and C4:
    //   - A_out(p, q, r): p contiguous in memory.
    //   - C4_param(p, s): p contiguous, s strided.
    //
    // With this schedule, each iteration of (r, q, s) computes a
    // vector of p-values using a contiguous load from C4 and a scalar
    // load from A, which is good for cache and SIMD.
    Target target = get_host_target();
    const int vec_width = natural_vector_size(target, type_of<num_t>());

    Var po("po"), pi("pi");

