    doitgen.update()
        .split(p, po, pi, vec_width)
        // loops: r (outer), q, s, po, pi (innermost, vectorized)
        .reorder(pi, po, s, q, r)
        .parallel(r)
        .vectorize(pi);

    // Bind JIT and compile
    doitgen.compile_jit(target);

